return {
  [668921023739392] = "A buzina ao longe ainda toca, e a glória de Wessel ainda flui aqui. A alma inflexível inclina a cabeça, mas o brilho da armadura permanece como sempre foi.",
  [668921023739136] = "Hee hee hee, ha ha ha... Por que você me deixou, mãe? \n Durma, durma profundamente. Borboleta frágil, pare de vagar.",
  [668921023738880] = "Quem roubou a casinha de uma tartaruga? \n Oh, Abundância, o poder da Abundância!",
  [668921023738624] = "Restam apenas memórias quebradas, cumprindo silenciosamente a promessa de um Guarda.",
  [668921023738368] = "A vontade motivada partiu, mas o majestoso Bark ainda ecoa. \n Os olhos leais ainda estão observando; as maçãs deste ano são perfumadas?",
  [668921023738112] = "Uma página que não deveria ser virada – é infortúnio ou destruição?",
  [668921023737856] = "Não importa o que tenha sido destruído, agora se tornou um eco distante.",
  [668921023737600] = "Zombando do riso e da tristeza, zombando também do fracasso e da Vitória. \n Seu dono partiu; esta é a marca de sua honra.",
  [668921023718912] = "Este retrato retrata um poeta que não é bom em poesia.",
  [668921023714304] = "As luzes noturnas acendem uma a uma, refletidas no rio Tussock que flui através de Tingen.",
  [668921023737344] = "O que está escondido na cartola? Flores de papel, lenços, cartas de baralho ou um grande e perigoso truque de mágica.",
  [668921023722496] = "Este retrato retrata um Light Chaser franco e firme.",
  [668921023722240] = "Este retrato retrata um chefe que está eternamente observando.",
  [668921023721984] = "Este retrato retrata uma garota proficiente em tecnologia mecânica.",
  [668921023721728] = "Este retrato retrata um trabalhador de escritório inteligente de Backlund.",
  [668921023721472] = "Este retrato retrata um fanático por biologia que adora cogumelos.",
  [668921023720960] = "Este retrato retrata um homem idoso que segue estritamente seu credo.",
  [668921023720704] = "Este retrato retrata uma pessoa que nunca traiu e olhou para a luz.",
  [668921023720448] = "Este retrato retrata um... um golden retriever com uma expressão gentil.",
  [668921023720192] = "Este retrato retrata um capitão que enfrenta diretamente a tempestade.",
  [668921023719680] = "Este retrato retrata uma garota nobre com um sorriso tranquilo.",
  [668921023719424] = "Este retrato retrata um Médium Espiritual que sempre lida com a morte.",
  [668921023719168] = "Este retrato retrata um Guardião com profundos olhos cinzentos.",
  [611673941516800] = "Uma refeição de trabalho encomendada pela senhorita Rozanne, feita com creme rico e ostras deliciosas.",
  [611673941516544] = "Uma refeição de trabalho pré-encomendada pela senhorita Rozanne. Carne de perna de cordeiro assada, com sucos integrais impregnados na carne tenra e mastigável.",
  [611673941510656] = "Se você puder ver esta descrição, isso prova que há um BUG. Por favor, denuncie.",
  [611673941508096] = "A fina carne picada de gengibre flutua na turva sopa dourada, o ar picante corre pela cavidade nasal e, depois de beber tudo, a garganta até o estômago queima até o fim.",
  [611673941507840] = "Uma combinação perfeita de grãos de café torrados escuros de alta qualidade e sabor doce de uva; refrescante sem perder o sabor.",
  [611673941507584] = "O aroma torrado é constante, a rima do malte é longa e o calor chega direto ao coração.",
  [611673941501952] = "Líquido âmbar com finos pedaços de gengibre flutuando nele. O tempero misturado com o aroma do álcool invade a garganta e o calor no peito desperta os nervos.",
  [611673941501696] = "Neste momento partilhamos este pôr-do-sol.",
  [611673941501184] = "Uma poção contendo a Energia da terra; uma leve sacudida faz parecer que veias terrestres estão surgindo na garrafa.",
  [611673941500928] = "Uma poção repleta de orvalho matinal da floresta e essência de videira, reunindo a vitalidade das plantas.",
  [611673941500672] = "Uma poção comum; depois de beber, você sente como se seu corpo tivesse recebido alguma força. Parece e tem gosto de leite...?",
  [611673941500416] = "Bife de carne de corte grosso, carbonizado e oleoso, com aroma de gordura grelhada no carvão. Uma refeição completa pode reabastecer sua força física.",
  [611673941500160] = "Uma sopa quente feita de ovo e leite; um leve gole restaura o ânimo.",
  [611673941499904] = "Uma lata recheada com vários frutos silvestres, mantendo o sabor agridoce. Pode ser aberto e consumido diretamente ou usado como geléia no pão.",
  [611673941499648] = "A recriação do lojista do pudim de limão real, com menos a doçura enjoativa do açúcar industrial e mais a delicadeza do trabalho artesanal.",
  [611673941499392] = "Uma xícara de chá doce e gelada, uma bebida de verão misturada com cubos de gelo e açúcar. Você pode tentar adicionar uma rodela de limão!",
  [611673941499136] = "Pão duro com sabor adstringente de farelo de trigo, ótima opção para encher o estômago.",
  [611673941496576] = "Este retrato retrata um Colecionador de Cadáveres pálido e silencioso.",
  [611673941495296] = "Este retrato retrata um escritor que sofre de procrastinação.",
  [611673941494016] = "Quando a luz da manhã atravessa as cortinas, a bela parece mudar de aparência. \n Sabor persistente, fragrância refrescante. Ainda abalado, um grande sonho.",
  [611673941493504] = "Um banco de madeira muito utilizado para descanso, que tem ocupado um pequeno período de tempo para muitos transeuntes.",
  [611673941493248] = "A pedra foi esculpida em linhas suaves. Que voz interior tem esta estátua silenciosa?",
  [611673941492992] = "Rosa Vermelha e Chama Negra se entrelaçam em torno da figura feminina. O escultor deixou deliberadamente as pontas dos dedos inacabadas – deixando o resto para o observador.",
  [611673941492736] = "A luz das estrelas e da lua são lançadas no mesmo galho de metal. Quando a vela está acesa, parece que você pode ouvir o refrão vindo de longe.",
  [611673941489664] = "Uma poção Berserk contendo a Ira de um Deus, um presente da fonte do poder.",
  [611673941489408] = "Uma poção Berserk feita através de Magia Ritual especial, eliminando a dor e o Horror, transformando-a brevemente em uma arma de combate.",
  [611673941489152] = "Uma poção especial contendo a iluminação de um Deus, um presente da fonte de espiritualidade.",
  [611673941488896] = "Uma poção especial feita através de Magia Ritual especial, capaz de preencher o vazio de espiritualidade e perceber segredos e o desconhecido.",
  [611673941488640] = "Uma poção de cura contendo a misericórdia de um Deus, um presente da fonte da vida.",
  [611673941488384] = "Uma poção de cura feita através de Magia Ritual especial, capaz de estimular os limites de autocura do corpo.",
  [611673941488128] = "Um sanduíche premium feito com ingredientes selvagens raros. Aproveite o sabor multicamadas; cada mordida contém uma bênção.",
  [611673941487872] = "Pão recheado com ingredientes de alta qualidade como vegetais, queijo e presunto. Duplique a delícia, energia restaurada!",
  [611673941487360] = "Uma fatia grossa de torrada com um tom dourado quente. A riqueza da manteiga e a suavidade do leite se entrelaçam na boca, tornando-se mais perfumadas à medida que você mastiga.",
  [611673941487104] = "Sopa de abóbora dourada e rica, fumegante, com leite e canela entrelaçados. O sabor é denso e doce, e o calor chega direto ao coração.",
  [611673941486848] = "Uma xícara de porcelana cheia de chá âmbar, o calor do chá preto envolto no doce aroma da cobertura.",
  [611673941486592] = "O corpo dourado do bolo é fofo como uma nuvem, com uma mistura de doçura azeda e leitosa se espalhando. Uma mordida inicia um dia feliz.",
