  [611673941485568] = "Uma poção Berserk inventada por um Professor de Poções, ajudando você a destruir todos os obstáculos e ilusões.",
  [611673941485312] = "Esta poção pode acender instantaneamente todo o potencial do corpo. Além de aumentar significativamente o Ataque por um curto período de tempo, também faz você esquecer o que é dor.",
