  [611673941483776] = "Esta poção tem um sabor doce e claro, com um leve amargor proveniente dos sucos das plantas. Além de ter excelentes efeitos curativos, é também uma bebida deliciosa.",
  [611673941483520] = "Uma poção de cura preparada por um Boticário. É acessível e eficaz, o que o torna muito popular entre Beyonders .",
  [611673941483264] = "Uma farta e grande porção de pão nutritivo, preparado através de um ritual especial para lhe proporcionar uma vitalidade crescente!",
